{
  "abilities": [
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "Aatrox heals for the post-mitigation bonus damage dealt, reduced to 25% against minions.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "Healing depends on bonus damage actually dealt and is reduced against minions."
        },
        {
          "citations": [
            {
              "quote": "Whenever Aatrox hits at least one enemy champion or large monster with a basic attack on-hit or an ability, Deathbringer Stance's current cooldown is reduced by 2 seconds, doubled to 4 if he hits with the Sweetspot of The Darkin Blade.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "Attacks and ability hits against champions or large monsters reduce the passive cooldown; Q sweetspots reduce it further."
        },
        {
          "citations": [
            {
              "quote": "The empowered attack will not trigger against structures and wards.",
              "source_id": "wiki:P"
            },
            {
              "quote": "Does not apply if Deathbringer Stance's attack is dodged, blocked or misses.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "Structures and wards cannot trigger the empowerment; a dodged, blocked or missed attack does not apply its bonus damage."
        },
        {
          "citations": [
            {
              "quote": "If Deathbringer Stance's empowered attack becomes available during a standard attack's windup, it will not be consumed or trigger the bonus damage.",
              "source_id": "wiki:P"
            },
            {
              "quote": "The cooldown reduction applies even if an ability's hit is countered by spell shield.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "An empowerment becoming ready during an ordinary attack's windup does not empower that attack; spell shields do not prevent eligible ability hits from reducing its cooldown."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Periodically, Aatrox's next basic attack deals bonus magic damage and heals him, based on the target's max health.",
              "source_id": "riot:P"
            },
            {
              "quote": "Innate: Periodically, Aatrox's next basic attack deals bonus magic damage based on the target's maximum health, healing him for the damage dealt.",
              "source_id": "wiki:P"
            }
          ],
          "id": "P.empowered_attack",
          "summary": "Periodically empowers the next basic attack with target maximum-health-based bonus magic damage and self-healing."
        }
      ],
      "slot": "P",
      "unsupported_claims": [
        "Every basic attack triggers the passive empowerment.",
        "The passive heals for a fixed amount regardless of damage dealt."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "First Cast: Aatrox's first strike affects a 625 × 180-unit rectangular area in the target direction, with him centered on the back line and the Sweetspot at the farthest edge.",
              "source_id": "wiki:Q"
            },
            {
              "quote": "Second Cast: Aatrox's second strike affects a trapezoidal area in the target direction, with the Sweetspot at the farthest edge.",
              "source_id": "wiki:Q"
            },
            {
              "quote": "Third Cast: Aatrox's third strike affects a 300-radius circular area centered on a target location that is 200 units in front of him, with a 180-radius Sweetspot within.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "The first two sweetspots are at the far edge; the third is the inner region of the circular strike."
        },
        {
          "citations": [
            {
              "quote": "The third cast, as well as the Sweetspot of the first and second cast, register their hit based on center range. The enemy's center must be within the hitbox to apply the effects.",
              "source_id": "wiki:Q"
            },
            {
              "quote": "Enemies must be within both areas to trigger the bonus damage, knock up and Deathbringer Stance's cooldown reduction.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "Sweetspot eligibility has specific hitbox requirements, including center-based checks; the first two require overlap with both component areas."
        },
        {
          "citations": [
            {
              "quote": "If Aatrox does not recast the ability within 4 seconds of the previous cast, it goes on cooldown.",
              "source_id": "wiki:Q"
            },
            {
              "quote": "This ability will cast from wherever the caster is at the end of the cast time.",
              "source_id": "wiki:Q"
            },
            {
              "quote": "Umbral Dash can be cast. Other abilities are disabled.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "Recasts have a limited window. E can reposition Aatrox during Q's cast, and the strike originates from his position when casting finishes."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Aatrox slams his greatsword down, dealing physical damage. He can swing three times, each with a different area of effect.",
              "source_id": "riot:Q"
            },
            {
              "quote": "The area varies and the damage increases per cast.",
              "source_id": "wiki:Q"
            }
          ],
          "id": "Q.three_strikes",
          "summary": "Up to three physical-damage area strikes, with a different shape and increasing damage on successive casts."
        },
        {
          "citations": [
            {
              "quote": "Enemies within each area's Sweetspot receive increased damage and are briefly knocked up.",
              "source_id": "wiki:Q"
            }
          ],
          "id": "Q.sweetspot",
          "summary": "Each strike has a sweetspot that deals increased damage and briefly knocks enemies up."
        }
      ],
      "slot": "Q",
      "unsupported_claims": [
        "Every enemy hit anywhere in Q's area is knocked up.",
        "Q automatically aims its sweetspot at enemies."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "If this hits an enemy champion or large monster, a tether is formed between the target and the ground beneath them for 1.5 seconds, during which they are revealed.",
              "source_id": "wiki:W"
            }
          ],
          "status": "supported",
          "summary": "Only champions and large monsters receive the tether, which reveals them while active."
        },
        {
          "citations": [
            {
              "quote": "Spell shield will block the chain's application and initial damage but not the aftereffects of one already applied.",
              "source_id": "wiki:W"
            }
          ],
          "status": "supported",
          "summary": "A spell shield blocks initial application and damage, but does not block an already-applied chain's aftereffects."
        },
        {
          "citations": [
            {
              "quote": "The impact area is oriented relative to Aatrox's position when the projectile hits, not where the projectile originated from.",
              "source_id": "wiki:W"
            },
            {
              "quote": "The location that the target is dragged to is not at the target's original location, but slightly closer towards Aatrox's position when the zone expires.",
              "source_id": "wiki:W"
            }
          ],
          "status": "supported",
          "summary": "Area orientation uses Aatrox's position at impact; the final pull point is slightly toward his position at zone expiration."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Aatrox smashes the ground, dealing damage to the first enemy hit.",
              "source_id": "riot:W"
            },
            {
              "quote": "Active: Aatrox sends a chain in the target direction that deals physical damage and slows the first enemy hit.",
              "source_id": "wiki:W"
            }
          ],
          "id": "W.first_hit",
          "summary": "Fires a directional chain that damages and slows the first enemy hit."
        },
        {
          "citations": [
            {
              "quote": "Champions and large monsters have to leave the impact area quickly or they will be dragged to the center and take the damage again.",
              "source_id": "riot:W"
            },
            {
              "quote": "If the tether is not broken by the end of its duration, the target is dealt the same physical damage again and pulled to the center of the area.",
              "source_id": "wiki:W"
            }
          ],
          "id": "W.delayed_pull",
          "summary": "A hit champion or large monster must escape the tether area promptly or be pulled toward its center and damaged again."
        }
      ],
      "slot": "W",
      "unsupported_claims": [
        "W tethers and pulls every type of enemy.",
        "The delayed pull is unavoidable after the initial hit."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "Passive: Aatrox heals for 16% (+ 1.3% per 100 bonus health) of non- persistent post-mitigation damage he deals against enemy champions.",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "Passive healing is based on eligible non-persistent damage after mitigation against enemy champions."
        },
        {
          "citations": [
            {
              "quote": "Umbral Dash resets Aatrox's basic attack timer and can be cast during his other abilities without cancelling them and vice versa.",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "The dash resets the basic attack timer and can overlap his other abilities without cancelling them."
        },
        {
          "citations": [
            {
              "quote": "The dash distance can be extended to up-to 500 units when targeting across terrain. It will only extend for the distance needed to cross the wall.",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "Targeting across terrain can extend the dash only as far as needed to cross, subject to the stated maximum."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Passively, Aatrox heals when damaging enemy champions.",
              "source_id": "riot:E"
            },
            {
              "quote": "Passive: Aatrox heals for the portion of the damage he deals to champions.",
              "source_id": "wiki:E"
            }
          ],
          "id": "E.damage_healing",
          "summary": "Passively heals Aatrox for a portion of eligible damage dealt to enemy champions."
        },
        {
          "citations": [
            {
              "quote": "On activation, he dashes in a direction.",
              "source_id": "riot:E"
            },
            {
              "quote": "Active: Aatrox dashes in the target direction.",
              "source_id": "wiki:E"
            }
          ],
          "id": "E.dash",
          "summary": "Activation dashes in the chosen direction."
        }
      ],
      "slot": "E",
      "unsupported_claims": [
        "E's passive heals from all damage against every target type.",
        "E grants an attack damage buff.",
        "E can cross any wall regardless of thickness."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "During World Ender, Aatrox gains bonus attack damage, has 5% increased size, is ghosted, and receives increased self-healing from all sources.",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "Healing amplification applies to self-healing from all sources; the form also grants ghosting and increased size."
        },
        {
          "citations": [
            {
              "quote": "Whenever Aatrox scores a champion takedown, he extends the duration by 5 seconds, up to its original length, and becomes unleashed again.",
              "source_id": "wiki:R"
            },
            {
              "quote": "These effects are refreshed and the duration is extended whenever Aatrox scores a champion takedown.",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "Champion takedowns refresh the effects and extend remaining duration, capped at the original duration."
        },
        {
          "citations": [
            {
              "quote": "Active: Aatrox unleashes his true form for 10 seconds, fearing nearby enemy minions and monsters for 3 seconds, during which they are gradually slowed by up to 99% over the duration.",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "The activation fear also affects nearby monsters."
        },
        {
          "citations": [
            {
              "quote": "World Ender persists through resurrection effects.",
              "source_id": "wiki:R"
            },
            {
              "quote": "World Ender's healing amplification applies to the health gained by resurrecting.",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "World Ender persists through resurrection effects and amplifies health gained from resurrection."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Aatrox unleashes his demonic form, fearing nearby enemy minions and gaining attack damage, increased healing, and Move Speed.",
              "source_id": "riot:R"
            },
            {
              "quote": "During this time, Aatrox has increased attack damage, self-healing, and is ghosted.",
              "source_id": "wiki:R"
            }
          ],
          "id": "R.empowered_form",
          "summary": "Temporarily transforms, gaining attack damage, movement speed and increased self-healing."
        },
        {
          "citations": [
            {
              "quote": "Aatrox unleashes his demonic form, fearing nearby enemy minions",
              "source_id": "riot:R"
            }
          ],
          "id": "R.fear",
          "summary": "Activation fears nearby enemy minions."
        },
        {
          "citations": [
            {
              "quote": "If he gets a takedown, this effect is extended.",
              "source_id": "riot:R"
            },
            {
              "quote": "These effects are refreshed and the duration is extended whenever Aatrox scores a champion takedown.",
              "source_id": "wiki:R"
            }
          ],
          "id": "R.takedown_extension",
          "summary": "Champion takedowns extend the empowered form."
        }
      ],
      "slot": "R",
      "unsupported_claims": [
        "World Ender itself grants resurrection.",
        "World Ender's activation fears enemy champions.",
        "Minion kills extend World Ender.",
        "World Ender grants damage reduction or invulnerability."
      ]
    }
  ]
}
